{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Human PET imaging with [18F]TRACK, a TrkB/C ligand containing an amide, fluoroaromatic, and basic pyrrolidine, demonstrates proven brain penetration and on-target CNS signal, supporting meaningful BBB access for the query's similar amide/basic-amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In rats, vornorexant, a close analogue with a triazole, amide, fluoroaromatic, and saturated ether-containing ring, achieved an unbound CSF/plasma AUC ratio of 0.46, a direct quantitative measure of meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Oral dosing of compound 21b in mice produced brain concentrations of 3.2 mg/g versus serum 1.1 mg/mL, demonstrating robust BBB penetration despite a tertiary amide, basic piperazine, and fluoroaromatic motif similar to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A rhesus monkey PET study showed that an H3R inverse agonist tracer with a basic piperidine and amide was not a P-gp substrate and entered the brain rapidly, mitigating the predicted efflux concern for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Dynamic PET in mice showed [18F]PB118, a hydroxamate/fluoroaromatic/tricyclic amine analogue, reached 7 %ID/cc in brain, classified as excellent brain uptake, supporting that moderately polar, ionizable scaffolds can achieve high CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: high-transfer in vivo evidence from human, NHP, pig, rat, and mouse consistently shows meaningful CNS penetration for analogues sharing the query's amide, basic amine/heterocycle, fluoroaromatic, and moderate lipophilicity; this direct evidence outweighs the uncertain physicochemical prior.",
  "evidence_gaps": [
    "No direct experimental BBB measurement for the exact query molecule; prediction relies on high-transfer analogues.",
    "Predicted low neutral fraction (0.01) and possible efflux liability are not experimentally resolved for the query.",
    "Quantitative brain/plasma or CSF exposure for the query is unavailable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

